@@ -14,8 +14,12 @@ export const DISCOUNT_CODES: Record<string, DiscountRule> = {
 /** The discount in cents that `code` gives on `subtotal` cents. 0 when the code does not apply. */
 export function discountFor(subtotal: number, code: string): number {
   const rule = DISCOUNT_CODES[code.trim().toUpperCase()];
-  if (!rule) return 0;
-  if (subtotal < rule.minSubtotal) return 0;
+  if (!rule || !meetsMinimum(subtotal, rule)) return 0;
   const amount = rule.kind === "percent" ? Math.round((subtotal * rule.value) / 100) : rule.value;
   return Math.min(amount, subtotal);
 }
+
+/** True when `subtotal` is enough for `rule`. Checkout uses it to explain why a code did not apply. */
+export function meetsMinimum(subtotal: number, rule: DiscountRule): boolean {
+  return subtotal > rule.minSubtotal;
+}

